using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Npgsql;

namespace Maxx.Infrastructure;

public static class DependencyInjection
{
    public static IServiceCollection AddInfrastructure(this IServiceCollection services, string connectionString)
    {
        services.AddNpgsqlDataSource(connectionString);

        services.AddDbContext<MaxxDbContext>((provider, options) =>
            MaxxDbContext.Configure(options, builder => builder.UseNpgsql(
                provider.GetRequiredService<NpgsqlDataSource>(),
                npgsql => npgsql.MigrationsHistoryTable(MaxxDbContext.MigrationsHistoryTable))));

        services.AddScoped<DatabaseMigrator>();
        services.AddScoped<DatabaseSeeder>();

        services.AddSingleton<ISenhaHasher, Argon2idSenhaHasher>();
        services.AddSingleton<ITokenGenerator, TokenGenerator>();

        services.AddScoped<IUnitOfWork, UnitOfWork>();
        services.AddScoped<ICadastroElegivelRepository, CadastroElegivelRepository>();
        services.AddScoped<IUsuarioRepository, UsuarioRepository>();
        services.AddScoped<ITermoDeUsoRepository, TermoDeUsoRepository>();
        services.AddScoped<IFamiliaDeSessaoRepository, FamiliaDeSessaoRepository>();
        services.AddScoped<IEscopoDeTurma, EscopoDeTurma>();
        services.AddScoped<IRecuperacaoDeSenhaRepository, RecuperacaoDeSenhaRepository>();
        services.AddScoped<IDemonstracaoRepository, DemonstracaoRepository>();
        services.AddScoped<IMedalhaRepository, MedalhaRepository>();
        services.AddScoped<IConsultaDoProfessor, ConsultaDoProfessor>();
        services.AddScoped<INotificacaoRepository, NotificacaoRepository>();
        services.AddScoped<IConsultaDePremios, ConsultaDePremios>();

        // Fila no Postgres (ADR 0008): a API e o worker enfileiram; só o worker consome.
        services.AddOptions<FilaOptions>();
        services.AddScoped<IFilaDeTrabalhos, FilaDeTrabalhos>();
        services.AddSingleton<TiposDeTrabalho>();
        services.AddSingleton<ConsumidorDeTrabalhos>();

        // Os tipos de trabalho. O e-mail sai só por eles, no worker; as opções (EmailOptions)
        // e o link do app (ILinkDoApp) vêm da borda.
        services.AddSingleton<IEmailSender, SmtpEmailSender>();
        services.AddTrabalho<EmailDeRecuperacao, EmailDeRecuperacaoHandler>();
        services.AddTrabalho<NotificarMedalhaRecebida, NotificarMedalhaRecebidaHandler>();
        services.AddTrabalho<RecalcularRaridade, RecalculoDeRaridade>();

        // Toda verificação registrada aqui entra no /ready.
        services.AddHealthChecks()
            .AddCheck<DatabaseReadinessCheck>("database", timeout: TimeSpan.FromSeconds(3));

        return services;
    }
}
using Npgsql;
using Testcontainers.PostgreSql;

namespace Maxx.Api.IntegrationTests;

public sealed class PostgresFixture : IAsyncLifetime
{
    private readonly PostgreSqlContainer _container = new PostgreSqlBuilder("postgres:18-alpine").Build();

    public async ValueTask InitializeAsync() => await _container.StartAsync();

    public async ValueTask DisposeAsync() => await _container.DisposeAsync();

    // Um banco vazio por teste: migration é estado global e não pode vazar entre testes.
    public async Task<string> CreateDatabaseAsync()
    {
        var name = $"maxx_{Guid.NewGuid():N}";

        await using var connection = new NpgsqlConnection(_container.GetConnectionString());
        await connection.OpenAsync();
        await using var command = new NpgsqlCommand($"CREATE DATABASE {name}", connection);
        await command.ExecuteNonQueryAsync();

        return new NpgsqlConnectionStringBuilder(_container.GetConnectionString()) { Database = name }.ConnectionString;
    }
}
using Maxx.Infrastructure.Persistence;
using Maxx.Infrastructure.Seed;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace Maxx.Api.IntegrationTests;

// diretorioDeDados: data/ do repositório, salvo quando o teste altera uma cópia.
// configuracao: chaves a mais, no formato do IConfiguration ("Jwt:Chave").
// servicos: troca de serviços depois dos da aplicação (relógio, hasher contado).
public sealed class MaxxApiFactory(
    string connectionString,
    string environment = "Development",
    string? diretorioDeDados = null,
    IReadOnlyDictionary<string, string>? configuracao = null,
    Action<IServiceCollection>? servicos = null)
    : WebApplicationFactory<Program>
{
    // Porta 1 recusa conexão: banco fora do ar sem depender de contêiner.
    public const string UnreachableDatabase =
        "Host=127.0.0.1;Port=1;Database=maxx;Username=maxx;Password=maxx;Timeout=2";

    // Fora de desenvolvimento a API não sobe sem chave de assinatura (gerada por execução)
    // nem sem a URL pública do app.
    public static IReadOnlyDictionary<string, string> ChaveDeTeste { get; } = new Dictionary<string, string>
    {
        ["Jwt:Chave"] = Convert.ToBase64String(System.Security.Cryptography.RandomNumberGenerator.GetBytes(48)),
        ["App:UrlPublica"] = "https://maxx.teste",
    };

    // Tudo o que a aplicação escreveu em log, de todos os níveis, já formatado.
    public ColetorDeLog Log { get; } = new();

    protected override void ConfigureWebHost(IWebHostBuilder builder)
    {
        builder.ConfigureLogging(logging => logging
            .AddProvider(Log)
            .AddFilter<ColetorDeLog>(category: null, LogLevel.Trace));

        if (servicos is not null)
        {
            builder.ConfigureServices(servicos);
        }

        builder.UseSetting("ConnectionStrings:Maxx", connectionString)
            .UseSetting($"{SeedOptions.Section}:{nameof(SeedOptions.DiretorioDeDados)}", diretorioDeDados ?? Repositorio.DiretorioDeDados)
            .UseEnvironment(environment);

        foreach (var (chave, valor) in configuracao ?? new Dictionary<string, string>())
        {
            builder.UseSetting(chave, valor);
        }
    }

    // O mesmo caminho do subcomando migrate, num escopo próprio.
    public async Task MigrateAsync(CancellationToken cancellationToken)
    {
        await using var scope = Services.CreateAsyncScope();
        await scope.ServiceProvider.GetRequiredService<DatabaseMigrator>().MigrateAsync(cancellationToken);
    }

    // O mesmo caminho do subcomando seed, num escopo próprio.
    public async Task<ResultadoDoSeedBase> SeedBaseAsync(CancellationToken cancellationToken)
    {
        await using var scope = Services.CreateAsyncScope();
        return await scope.ServiceProvider.GetRequiredService<DatabaseSeeder>().SeedBaseAsync(cancellationToken);
    }

    public async Task<ResultadoDoSeedDemo> SeedDemoAsync(CancellationToken cancellationToken)
    {
        await using var scope = Services.CreateAsyncScope();
        return await scope.ServiceProvider.GetRequiredService<DatabaseSeeder>().SeedDemoAsync(cancellationToken);
    }
}
namespace Maxx.Application;

// Um e-mail pronto para sair. O texto pode levar segredo (o link de recuperação): nunca
// vai para log, nem pelo ToString.
public sealed record MensagemDeEmail(string Para, string Assunto, string Texto)
{
    public override string ToString() => $"MensagemDeEmail {{ Assunto = {Assunto} }}";
}

// Entrega um e-mail ao servidor SMTP. Chamado só por handler de trabalho, no worker: quem
// pede o e-mail enfileira um trabalho na fila do Postgres e responde (decisoes/README.md,
// Envio de e-mail). Falha lança, e o trabalho volta com recuo.
public interface IEmailSender
{
    Task EnviarAsync(MensagemDeEmail mensagem, CancellationToken cancellationToken);
}
using System.Reflection;
using System.Text.Json.Serialization;
using Maxx.Api.Autenticacao;
using Maxx.Api.Demonstracao;
using Maxx.Api.Erros;
using Maxx.Api.Health;
using Maxx.Api.LimiteDeTaxa;
using Maxx.Api.Medalhas;
using Maxx.Api.OpenApi;
using Maxx.Api.Premios;
using Maxx.Infrastructure;
using Maxx.Infrastructure.Fila;
using Maxx.Infrastructure.Persistence;
using Maxx.Infrastructure.Seed;

// `Maxx.Api migrate` roda as migrations e sai. É o comando do contêiner de migração.
var isMigrate = args is ["migrate", ..];

// `Maxx.Api seed <base|demo>` grava os dados de data/ e sai. Idempotente.
var isSeed = args is ["seed", ..];

// `Maxx.Api anular-medalha <id> --instituicao <e-mail>` anula uma medalha e sai: a anulação
// da fase 1, por comando administrativo (ComandoDeAnulacao).
var isAnulacao = args is [ComandoDeAnulacao.Nome, ..];

// `Maxx.Api worker` consome a fila de trabalhos do Postgres (ADR 0008), sem servidor HTTP.
// É o comando do contêiner do worker; as réplicas da API só enfileiram.
if (args is ["worker", ..])
{
    var worker = Host.CreateApplicationBuilder(args[1..]);
    worker.Services.AddSingleton(TimeProvider.System);
    worker.Services.AddInfrastructure(
        worker.Configuration.GetConnectionString("Maxx")
            ?? throw new InvalidOperationException("ConnectionStrings:Maxx não configurada."));
    worker.AddEnvioDeEmail(exigirUrl: true);
    worker.Services.AddWorker();
    await worker.Build().RunAsync();
    return 0;
}

// A geração do OpenAPI no build sobe a aplicação sem servidor e sem banco.
var isOpenApiGeneration = Assembly.GetEntryAssembly()?.GetName().Name == "GetDocument.Insider";

var builder = WebApplication.CreateBuilder(
    isMigrate ? args[1..]
    : isSeed ? args[Math.Min(2, args.Length)..]
    : isAnulacao ? args[Math.Min(ComandoDeAnulacao.Argumentos, args.Length)..]
    : args);

var connectionString = builder.Configuration.GetConnectionString("Maxx")
    ?? (isOpenApiGeneration ? "Host=openapi-generation" : null)
    ?? throw new InvalidOperationException("ConnectionStrings:Maxx não configurada.");

builder.Services.AddProblemDetails(Erro.Customizar);

// Número só como número: o padrão web aceita "42" em texto, e o contrato viraria
// `number | string` em todo campo numérico do cliente TypeScript.
builder.Services.ConfigureHttpJsonOptions(options =>
    options.SerializerOptions.NumberHandling = JsonNumberHandling.Strict);

builder.Services.AddOpenApi(options => options
    .AddDocumentTransformer((document, _, _) =>
    {
        document.Info.Title = "Maxx API";
        document.Info.Version = "v1";
        return Task.CompletedTask;
    })
    .AddBearerSecurity());
