using System.Text.Json;
using Maxx.Application.Fila;
using Maxx.Infrastructure.Persistence;
using Microsoft.Extensions.DependencyInjection;

namespace Maxx.Infrastructure.Fila;

// Só acrescenta a linha ao DbContext do escopo: grava junto com a escrita de quem chamou.
internal sealed class FilaDeTrabalhos(MaxxDbContext db, TimeProvider clock) : IFilaDeTrabalhos
{
    public void Enfileirar<TCarga>(TCarga carga, DateTimeOffset? disponivelEm = null)
        where TCarga : ICargaDeTrabalho
    {
        ArgumentNullException.ThrowIfNull(carga);
        var agora = clock.GetUtcNow();
        db.Add(new Trabalho
        {
            Tipo = TCarga.Tipo,
            Carga = JsonSerializer.Serialize(carga, JsonSerializerOptions.Web),
            CriadoEm = agora,
            DisponivelEm = disponivelEm ?? agora,
        });
    }
}

// Um tipo de trabalho que o worker sabe executar: o nome gravado na linha e como
// transformar a carga em JSON numa chamada ao handler.
public sealed class TipoDeTrabalho(string nome, Func<IServiceProvider, string, CancellationToken, Task> executar)
{
    public string Nome { get; } = nome;

    internal Task ExecutarAsync(IServiceProvider servicos, string carga, CancellationToken cancellationToken) =>
        executar(servicos, carga, cancellationToken);
}

public sealed class TiposDeTrabalho(IEnumerable<TipoDeTrabalho> tipos)
{
    // Dois handlers para o mesmo nome é erro de registro: falha ao montar, não no meio da fila.
    private readonly Dictionary<string, TipoDeTrabalho> _porNome = tipos.ToDictionary(tipo => tipo.Nome, StringComparer.Ordinal);

    public TipoDeTrabalho? Buscar(string nome) => _porNome.GetValueOrDefault(nome);
}

public sealed class FilaOptions
{
    // Espera entre duas consultas quando a fila está vazia.
    public TimeSpan IntervaloOcioso { get; set; } = TimeSpan.FromSeconds(1);

    // Passado disso, o trabalho é cancelado e conta como falha: um handler travado não pode
    // segurar o lock da linha para sempre.
    public TimeSpan TempoMaximoPorTrabalho { get; set; } = TimeSpan.FromSeconds(60);
}

public static class FilaServiceCollectionExtensions
{
    // Registra o handler de um tipo. API e worker registram os mesmos tipos: quem enfileira
    // e quem executa conhecem o mesmo nome.
    public static IServiceCollection AddTrabalho<TCarga, THandler>(this IServiceCollection services)
        where TCarga : ICargaDeTrabalho
        where THandler : class, ITrabalhoHandler<TCarga>
    {
        services.AddScoped<ITrabalhoHandler<TCarga>, THandler>();
        services.AddSingleton(new TipoDeTrabalho(TCarga.Tipo, async (servicos, json, cancellationToken) =>
        {
            var carga = JsonSerializer.Deserialize<TCarga>(json, JsonSerializerOptions.Web)
                ?? throw new InvalidOperationException($"Carga vazia para o trabalho {TCarga.Tipo}.");
            await servicos.GetRequiredService<ITrabalhoHandler<TCarga>>().ExecutarAsync(carga, cancellationToken);
        }));
        return services;
    }

    // O consumo contínuo, só no processo do worker (`Maxx.Api worker`). As réplicas da API
    // enfileiram e não consomem.
    public static IServiceCollection AddWorker(this IServiceCollection services)
    {
        services.AddHostedService<ServicoDoWorker>();
        return services;
    }
}
using Maxx.Application.Fila;
using Maxx.Application.Medalhas;
using Maxx.Domain.Notificacoes;

namespace Maxx.Application.Notificacoes;

public interface INotificacaoRepository
{
    void Adicionar(Notificacao notificacao);

    Task<bool> ExisteAsync(Guid usuarioId, TipoDeNotificacao tipo, Guid referenciaId, CancellationToken cancellationToken);
}

// No worker: grava a notificação de medalha recebida (produto.md 8). Uma por medalha, mesmo
// que o trabalho rode de novo; nenhuma para medalha que já foi anulada ou apagada pela purga.
public sealed class NotificarMedalhaRecebidaHandler(
    IMedalhaRepository medalhas,
    INotificacaoRepository notificacoes,
    IUnitOfWork unitOfWork,
    TimeProvider relogio) : ITrabalhoHandler<NotificarMedalhaRecebida>
{
    public async Task ExecutarAsync(NotificarMedalhaRecebida carga, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(carga);

        var medalha = await medalhas.BuscarAsync(carga.MedalhaId, cancellationToken);
        if (medalha is null || !medalha.EstaAtiva
            || await notificacoes.ExisteAsync(medalha.AlunoId, TipoDeNotificacao.MedalhaRecebida, medalha.Id, cancellationToken))
        {
            return;
        }

        notificacoes.Adicionar(Notificacao.MedalhaRecebida(medalha, relogio.GetUtcNow()));
        await unitOfWork.SalvarAsync(cancellationToken);
    }
}
namespace Maxx.Application;

// Um pedido que a aplicação recusa por regra, não por falha: a borda traduz o tipo em
// status HTTP e devolve o código no formato único de erro. A mensagem é só para o log.
public sealed class RecusaException : Exception
{
    public RecusaException()
    {
        Codigo = string.Empty;
    }

    public RecusaException(string message) : base(message)
    {
        Codigo = string.Empty;
    }

    public RecusaException(string message, Exception innerException) : base(message, innerException)
    {
        Codigo = string.Empty;
    }

    public RecusaException(TipoDeRecusa tipo, string codigo, string? motivoParaLog = null)
        : base(motivoParaLog ?? codigo)
    {
        Tipo = tipo;
        Codigo = codigo;
    }

    public TipoDeRecusa Tipo { get; }

    // Estável e em kebab-case: é o que o cliente usa para escolher a mensagem amigável.
    public string Codigo { get; }
}

public enum TipoDeRecusa
{
    Invalido,
    NaoEncontrado,
    Conflito,
    NaoAutorizado,

    // Autenticado, mas sem direito sobre o recurso: o escopo de turma do professor.
    Proibido,
}

// Gravação recusada por uma unicidade do banco: a corrida que a checagem prévia não
// consegue fechar sozinha.
public sealed class ConflitoDeUnicidadeException : Exception
{
    public ConflitoDeUnicidadeException()
    {
    }

    public ConflitoDeUnicidadeException(string message) : base(message)
    {
    }

    public ConflitoDeUnicidadeException(string message, Exception innerException) : base(message, innerException)
    {
    }

    public ConflitoDeUnicidadeException(Unicidade unicidade, Exception innerException)
        : base($"Unicidade violada: {unicidade}.", innerException)
    {
        Unicidade = unicidade;
    }

    public Unicidade Unicidade { get; }
}

public enum Unicidade
{
    Outra,
    ContaPorCadastro,
    Prefixo,

    // Duas medalhas ativas com a mesma chave de deduplicação: a mesma vaga do período.
    MedalhaAtiva,
}

// Gravação recusada porque a linha mudou desde a leitura (xmin): outro pedido chegou
// antes. Quem chama decide se relê e tenta de novo.
public sealed class ConflitoDeConcorrenciaException : Exception
{
    public ConflitoDeConcorrenciaException()
    {
    }

    public ConflitoDeConcorrenciaException(string message) : base(message)
    {
    }

    public ConflitoDeConcorrenciaException(string message, Exception innerException) : base(message, innerException)
    {
    }
}

public interface IUnitOfWork
{
    // Lança ConflitoDeUnicidadeException quando o banco recusa por unicidade e
    // ConflitoDeConcorrenciaException quando a linha mudou desde a leitura.
    Task SalvarAsync(CancellationToken cancellationToken);

    // Esquece o que o escopo leu e alterou, para reler do banco.
    void Descartar();
}
namespace Maxx.Application.Medalhas;

// Os códigos de recusa da medalha, como o cliente os recebe em ProblemDetails.
public static class CodigosDaMedalha
{
    // A turma não é do professor, ou não é do semestre vigente.
    public const string ForaDoEscopo = "fora-do-escopo";

    // O aluno não tem conta, não está matriculado na turma ou não existe.
    public const string AlunoForaDaTurma = "aluno-fora-da-turma";

    public const string ItemNaoEncontrado = "item-nao-encontrado";

    public const string ExAluno = "ex-aluno";

    // Hoje está fora do semestre da turma ou entre dois bimestres: a medalha não teria
    // bimestre.
    public const string ForaDoPeriodo = "fora-do-periodo";

    public const string ItemForaDeVigencia = "item-fora-de-vigencia";

    public const string ItemDeOutroCurso = "item-de-outro-curso";

    // O aluno já tem, nessa matéria e nesse período, tantas medalhas desse item quanto o
    // limite do catálogo.
    public const string LimiteAtingido = "limite-atingido";

    // Anulação: o id não é de medalha nenhuma.
    public const string MedalhaNaoEncontrada = "medalha-nao-encontrada";

    // Anulação: o e-mail informado não é de uma conta com o papel de instituição.
    public const string SemContaDeInstituicao = "sem-conta-de-instituicao";
}
using Maxx.Application;
using Microsoft.EntityFrameworkCore;
using Npgsql;

namespace Maxx.Infrastructure.Persistence;

// Grava o que o escopo acumulou. Unicidade violada vira ConflitoDeUnicidadeException com
// o nome da regra, para a Application responder com o código certo sem conhecer o banco.
internal sealed class UnitOfWork(MaxxDbContext db) : IUnitOfWork
{
    private static readonly Dictionary<string, Unicidade> _porIndice = new(StringComparer.Ordinal)
    {
        ["ix_usuario_cadastro_elegivel_id"] = Unicidade.ContaPorCadastro,
        ["pk_prefixo_reservado"] = Unicidade.Prefixo,
        ["ix_medalha_chave_ativa"] = Unicidade.MedalhaAtiva,
    };

    public async Task SalvarAsync(CancellationToken cancellationToken)
    {
        try
        {
            await db.SaveChangesAsync(cancellationToken);
        }
        catch (DbUpdateException falha) when (falha.InnerException is PostgresException
        {
            SqlState: PostgresErrorCodes.UniqueViolation,
        } postgres)
        {
            throw new ConflitoDeUnicidadeException(
                _porIndice.GetValueOrDefault(postgres.ConstraintName ?? string.Empty, Unicidade.Outra), falha);
        }
        catch (DbUpdateConcurrencyException falha)
        {
            throw new ConflitoDeConcorrenciaException("A linha mudou desde a leitura.", falha);
        }
    }

    public void Descartar() => db.ChangeTracker.Clear();
}

