    {
        var codigo = recusa switch
        {
            RecusaDaConcessao.ExAluno => CodigosDaMedalha.ExAluno,
            RecusaDaConcessao.ForaDoSemestreDaTurma or RecusaDaConcessao.ForaDeBimestre => CodigosDaMedalha.ForaDoPeriodo,
