    public static ComentarioResponse De(ComentarioLido comentario) => new(
        comentario.Id,
        new AutorDoComentarioResponse(comentario.Autor.Id, comentario.Autor.NomeDeExibicao, comentario.Autor.Arroba),
        comentario.Texto,
        comentario.CriadoEm);
}

// proximo vem nulo na última página.
public sealed record PaginaDeComentariosResponse(IReadOnlyList<ComentarioResponse> Itens, string? Proximo);

