import { createApiClient, type ApiClient } from "@maxx/api-client";
import { createContext, useContext, type ReactNode } from "react";
import { Platform } from "react-native";

// Origem única (ADR 0001): na web a API está no mesmo host, sob /api. No nativo, a URL
// pública vem de EXPO_PUBLIC_API_URL, que não é segredo e vai para o binário.
export function defaultBaseUrl(): string {
  return Platform.OS === "web" ? "" : (process.env.EXPO_PUBLIC_API_URL ?? "");
}

const ApiClientContext = createContext<ApiClient | null>(null);

export function ApiClientProvider({
  client,
  children,
}: {
  client: ApiClient;
  children: ReactNode;
}) {
  return (
    <ApiClientContext.Provider value={client}>
      {children}
    </ApiClientContext.Provider>
  );
}

export function useApiClient(): ApiClient {
  const client = useContext(ApiClientContext);
  if (!client) {
    throw new Error("useApiClient fora do ApiClientProvider.");
  }
  return client;
}

export { createApiClient };
import { codigoDoErro, mensagemDaFalha, mensagemDeErro } from "./erros";

// Uma recusa da API, já com a mensagem amigável. O código fica para a tela decidir onde
// mostrar (num campo, abaixo do botão, levando a outra rota).
export class FalhaDaApi extends Error {
  constructor(readonly codigo: string | undefined) {
    super(mensagemDeErro(codigo));
    this.name = "FalhaDaApi";
  }

  static doCorpo(corpo: unknown): FalhaDaApi {
    return new FalhaDaApi(codigoDoErro(corpo));
  }
}

// O que mostrar para qualquer erro de uma chamada: a recusa da API ou a falha de rede.
export function falhaParaTela(erro: unknown): {
  codigo?: string;
  mensagem: string;
} {
  return erro instanceof FalhaDaApi
    ? { codigo: erro.codigo, mensagem: erro.message }
    : {
        codigo: erro instanceof TypeError ? "sem-conexao" : undefined,
        mensagem: mensagemDaFalha(erro),
      };
}
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";

import { useApiClient } from "../api/ApiClientProvider";
import { FalhaDaApi } from "../api/FalhaDaApi";

// As consultas e a concessão do professor (passo 6). O escopo de turma é conferido pela
// API no banco: uma turma que não é dele responde 403 com `fora-do-escopo`.

export function useTurmasDoProfessor() {
  const client = useApiClient();

  return useQuery({
    queryKey: ["professor", "turmas"],
    queryFn: async () => {
      const { data, error } = await client.GET("/api/v1/professor/turmas");
      if (!data) {
        throw FalhaDaApi.doCorpo(error);
      }
      return data;
    },
  });
}

export function useAlunosDaTurma(turmaId: string) {
  const client = useApiClient();

  return useQuery({
    queryKey: ["professor", "turmas", turmaId, "alunos"],
    queryFn: async () => {
      const { data, error } = await client.GET(
        "/api/v1/professor/turmas/{turmaId}/alunos",
        { params: { path: { turmaId } } },
      );
      if (!data) {
        throw FalhaDaApi.doCorpo(error);
      }
      return data;
    },
  });
}

// O catálogo muda só com o seed: pode ficar em cache por mais tempo.
export function useMedalhasDoCatalogo() {
  const client = useApiClient();

  return useQuery({
    queryKey: ["professor", "medalhas"],
    staleTime: 10 * 60_000,
    queryFn: async () => {
      const { data, error } = await client.GET("/api/v1/professor/medalhas");
      if (!data) {
        throw FalhaDaApi.doCorpo(error);
      }
      return data;
    },
  });
}

// Concedida, a lista da turma é lida de novo: a medalha nova aparece na linha do aluno.
export function useConcederMedalha(turmaId: string) {
  const client = useApiClient();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (pedido: { alunoId: string; item: string }) => {
      const { data, error } = await client.POST(
        "/api/v1/professor/turmas/{turmaId}/medalhas",
        { params: { path: { turmaId } }, body: pedido },
      );
      if (!data) {
        throw FalhaDaApi.doCorpo(error);
      }
      return data;
    },
    onSuccess: () =>
      queryClient.invalidateQueries({
        queryKey: ["professor", "turmas"],
      }),
  });
}

