  const instituicao = sql(
    `SELECT c.email FROM cadastro_elegivel c
     JOIN usuario u ON u.cadastro_elegivel_id = c.id
     WHERE c.papeis & 4 = 4 ORDER BY c.email LIMIT 1;`,
  );
  return execFileSync(
    "docker",
    [
      "compose",
      "run",
      "--rm",
