import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

import { expect, test } from "@playwright/test";

import { novaConta } from "../tests/apoio/contas";
import { matricular, novaProfessora } from "../tests/apoio/medalhas";

const SAIDA = "${S}";

test("captura do novo post", async ({ page, request }, info) => {
  const aluno = await novaConta(request, "Ana Souza");
  const professora = await novaProfessora(request);
  matricular(aluno, professora.turmaId);

  const login = await request.post("/api/v1/auth/login", { data: { identificador: professora.email, senha: professora.senha } });
  const token = (await login.json()).accessToken;
  const autorizacao = { Authorization: \`Bearer \${token}\` };
  const alunos = await (await request.get(\`/api/v1/professor/turmas/\${professora.turmaId}/alunos\`, { headers: autorizacao })).json();
  const alunoId = alunos.find((linha: { arroba: string }) => linha.arroba === \`@\${aluno.prefixo}-CC\`).id;
  for (const item of ["M01", "M03"]) {
    expect((await request.post(\`/api/v1/professor/turmas/\${professora.turmaId}/medalhas\`, { headers: autorizacao, data: { alunoId, item } })).status()).toBe(201);
  }

  // A foto do campus da prancheta do feed, recortada num quadrado, como JPEG.
  const prancheta = readFileSync(path.resolve(__dirname, "../../design/telas/feed-claro.png")).toString("base64");
  await page.setContent("<canvas id=c width=900 height=900></canvas>");
  const jpeg = await page.evaluate(async (dados) => {
    const imagem = new Image();
    imagem.src = \`data:image/png;base64,\${dados}\`;
    await imagem.decode();
    const canvas = document.getElementById("c") as HTMLCanvasElement;
    canvas.getContext("2d")!.drawImage(imagem, 90, 318, 600, 600, 0, 0, 900, 900);
    return canvas.toDataURL("image/jpeg", 0.92).split(",")[1];
  }, prancheta);
  const foto = path.join(SAIDA, "campus.jpg");
  writeFileSync(foto, Buffer.from(jpeg!, "base64"));

  await page.goto("/login");
  await page.getByLabel("RA ou e-mail").fill(aluno.ra);
  await page.getByLabel("Senha", { exact: true }).fill(aluno.senha);
  await page.getByRole("button", { name: "Entrar" }).click();
  await page.getByRole("button", { name: "Novo post" }).click();
  await expect(page.getByText("Banco de Dados · 2º bimestre").first()).toBeVisible({ timeout: 15_000 }).catch(() => {});

  await page.screenshot({ path: path.join(SAIDA, \`novo-post-vazio-\${info.project.name}.png\`), fullPage: true });

  const seletor = page.waitForEvent("filechooser");
  await page.getByRole("button", { name: "Escolher foto" }).click();
  await (await seletor).setFiles(foto);
  await expect(page.getByTestId("previa-da-foto")).toBeVisible();
  await page.getByLabel("Legenda").fill("Nota 10 em Banco de Dados! Valeu, professora.");
  await page.getByRole("checkbox").first().click();

  await page.screenshot({ path: path.join(SAIDA, \`novo-post-preenchido-\${info.project.name}.png\`), fullPage: true });

  await page.getByRole("button", { name: "Publicar" }).click();
  await expect(page.getByTestId("arroba")).toBeVisible();
  const post = await (await request.get("/api/v1/feed", { headers: { Authorization: \`Bearer \${(await (await request.post("/api/v1/auth/login", { data: { identificador: aluno.ra, senha: aluno.senha } })).json()).accessToken}\` } })).json();
  writeFileSync(path.join(SAIDA, \`feed-depois-\${info.project.name}.json\`), JSON.stringify(post, null, 2));
});
