import { StyleSheet, Text, View } from "react-native";

import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { raios, tiers, type Raridade, type Tier } from "../theme/tokens";
import { Medalhao, type Glifo } from "./Medalhao";
import { rotulosDeRaridade, rotulosDeTier } from "./rotulos";

interface FaixaPremioProps {
  nome: string;
  tier: Tier;
  raridade: Raridade;
  glifo: Glifo;
  pontos: number;
  // Sob os pontos, como "foto validada".
  nota?: string;
  // Acima do nome, como "Último troféu" no perfil.
  rotulo?: string;
}

// A faixa do prêmio: medalhão, nome, tier e raridade, pontos à direita. O tier também vai em
// texto, e a raridade depois dele, porque os ornamentos sozinhos não dizem o nome.
export function FaixaPremio({
  nome,
  tier,
  raridade,
  glifo,
  pontos,
  nota,
  rotulo,
}: FaixaPremioProps) {
  const { name, colors } = useTheme();

  return (
    <View
      testID="faixa"
      style={[styles.faixa, { backgroundColor: colors.surface }]}
    >
      <Medalhao tier={tier} glifo={glifo} raridade={raridade} />

      <View style={styles.textos}>
        {rotulo && (
          <Text style={[textStyles.rotulo, { color: colors.ink2 }]}>
            {rotulo}
          </Text>
        )}
        <Text style={[textStyles.secao, { color: colors.ink }]}>{nome}</Text>
        <Text style={[textStyles.legenda, { color: colors.ink2 }]}>
          <Text style={[styles.tier, { color: tiers[tier].texto[name] }]}>
            {rotulosDeTier[tier]}
          </Text>
          {` · ${rotulosDeRaridade[raridade]}`}
        </Text>
      </View>

      <View style={styles.pontos}>
        <Text style={[textStyles.pontos, { color: colors.ink }]}>
          {`+${pontos}`}
        </Text>
        {nota && (
          <Text style={[textStyles.legenda, { color: colors.ink2 }]}>
            {nota}
          </Text>
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
import { StyleSheet, Text, View } from "react-native";

import { fontFamily } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { raios, tamanhos } from "../theme/tokens";

interface AvatarProps {
  // Nome de exibição: as iniciais saem dele. Fotos entram quando existirem.
  nome: string;
  size?: number;
}

// Só com as cores do token: aluno nunca é pintado com cor de tier. O anel dourado do próprio
// aluno fica para os passos 7 e 11.
export function Avatar({ nome, size = tamanhos.avatarPost }: AvatarProps) {
  const { colors } = useTheme();

  return (
    <View
      accessible
      role="img"
      aria-label={nome}
      style={[
        styles.circulo,
        {
          width: size,
          height: size,
          backgroundColor: colors.avatarBg,
        },
      ]}
    >
      <Text
        numberOfLines={1}
        style={[
          styles.iniciais,
          { color: colors.avatarFg, fontSize: Math.round(size * 0.4) },
        ]}
      >
        {iniciais(nome)}
      </Text>
    </View>
  );
}

// Primeira letra do primeiro e do último nome: "Ana Paula Souza" vira AS.
export function iniciais(nome: string) {
  const nomes = nome.trim().split(/\s+/);
  const primeira = (palavra: string | undefined) =>
    Array.from(palavra ?? "")[0] ?? "";
  const ultimo = nomes.length > 1 ? nomes[nomes.length - 1] : undefined;
