import { useSessao } from "../sessao/SessaoProvider";
import { textStyles } from "../theme/fonts";
import { ThemePreferenceControl } from "../theme/ThemePreferenceControl";
import { useTheme } from "../theme/ThemeProvider";

// O início até o feed chegar, no passo 7: quem entrou, o tema e a saída. Para o professor,
// a entrada das turmas e da concessão de medalha no passo 6; para o aluno, o novo post, até
// o "+" do cabeçalho do feed.
export function InicioProvisorio() {
  const { colors } = useTheme();
  const router = useRouter();
  const { sair } = useSessao();
  const eu = useEu();

  return (
    <Screen aboveNav>
      <View style={styles.coluna}>
        <Logo largura={160} />

        {eu.isPending && <ActivityIndicator color={colors.ink2} />}
        {eu.isError && <ErrorState onRetry={() => void eu.refetch()} />}
        {eu.isSuccess && (
  it("o professor vê Minhas turmas; o aluno, não", async () => {
    const comPapeis = (papeis: string[]) =>
      jest.fn(async (pedido: Request) =>
        new URL(pedido.url).pathname === "/api/v1/eu"
          ? json(200, { id: ANA, papeis, arroba: "@renataA-PROF" })
          : new Response(null, { status: 404 }),
      );

    const professor = await renderComApi(
      <InicioProvisorio />,
      comPapeis(["professor"]),
    );
    await apertarBotao("Minhas turmas");
    expect(mockRoteador.push).toHaveBeenCalledWith("/turmas");
    professor.unmount();

    await renderComApi(<InicioProvisorio />, comPapeis(["aluno"]));
    expect(await screen.findByTestId("arroba")).toBeOnTheScreen();
    expect(screen.queryByRole("button", { name: "Minhas turmas" })).toBeNull();
  });
});
    mensagem="Os avisos da faculdade, do curso e das turmas vão aparecer aqui."
  />
);

