// Para onde voltar depois do login: o deep link /post/:id fica atrás do login (produto.md
// 6.1), e quem chega sem sessão entra e cai no post. Só caminho interno do app, sem
// esquema, sem host e sem "//": um link de fora não pode mandar ninguém para outro site.
const CAMINHO_INTERNO = /^\/(?!\/)[A-Za-z0-9\-_/]*$/;

export function destinoSeguro(voltar: unknown): string | null {
  return typeof voltar === "string" &&
    CAMINHO_INTERNO.test(voltar) &&
    voltar !== "/"
    ? voltar
    : null;
}

