import { readFileSync } from "node:fs";
import path from "node:path";

import { expect, test, type APIRequestContext, type Page } from "@playwright/test";

import { novaConta } from "../tests/apoio/contas";
import { matricular, novaProfessora } from "../tests/apoio/medalhas";

// Captura temporária, fora do git: feed e comentários ao lado da prancheta.
const SAIDA =
  "C:/Users/GUILHE~1/AppData/Local/Temp/claude/C--Users-Guilherme-Gimenes-Documents-Repos-tcc-maxx-engenheiro/db2e3dff-90c5-43a0-a9fa-f91217b12056/scratchpad";

async function token(request: APIRequestContext, identificador: string, senha: string) {
  const resposta = await request.post("/api/v1/auth/login", { data: { identificador, senha } });
  return { Authorization: `Bearer ${(await resposta.json()).accessToken}` };
}

async function lado(page: Page, nossa: string, prancheta: string, saida: string, legenda: [string, string]) {
  const dados = (arquivo: string) => `data:image/png;base64,${readFileSync(arquivo).toString("base64")}`;
  await page.setViewportSize({ width: 1600, height: 900 });
  await page.setContent(`
    <body style="margin:0;background:#888;font:600 28px sans-serif;color:#fff">
      <div id="par" style="display:flex;gap:24px;padding:24px;width:max-content">
        <figure style="margin:0"><figcaption style="padding-bottom:12px">${legenda[0]}</figcaption><img src="${dados(prancheta)}" width="780"></figure>
        <figure style="margin:0"><figcaption style="padding-bottom:12px">${legenda[1]}</figcaption><img src="${dados(nossa)}" width="780"></figure>
      </div>
    </body>`);
  await page.locator("#par").screenshot({ path: saida });
}

test("feed e comentários", async ({ page, request }, info) => {
  const tema = info.project.name;
  const ana = await novaConta(request, "Ana Souza");
  const joao = await novaConta(request, "João Lima");
  const professora = await novaProfessora(request);
  matricular(ana, professora.turmaId);
  matricular(joao, professora.turmaId);

  const daAna = await token(request, ana.ra, ana.senha);
  const doJoao = await token(request, joao.ra, joao.senha);
  const daProfessora = await token(request, professora.email, professora.senha);
  const n = ana.ra.slice(-4);
  await request.patch("/api/v1/eu/perfil", { headers: daAna, data: { prefixo: `anaSouza${n}` } });
  await request.patch("/api/v1/eu/perfil", { headers: doJoao, data: { prefixo: `joaoLima${n}` } });

  const alunos = await (await request.get(`/api/v1/professor/turmas/${professora.turmaId}/alunos`, { headers: daProfessora })).json();
  const id = (nome: string) => alunos.find((linha: { nomeDeExibicao: string }) => linha.nomeDeExibicao === nome).id;
  const conceder = async (aluno: string, item: string) =>
    (await (await request.post(`/api/v1/professor/turmas/${professora.turmaId}/medalhas`, { headers: daProfessora, data: { alunoId: id(aluno), item } })).json()).id;
  const medalhaDoJoao = await conceder("João Lima", "M03");
  const medalhaDaAna = await conceder("Ana Souza", "M01");

  // O post do João primeiro, só com a medalha e a legenda; depois o da Ana, com a foto.
  await request.post("/api/v1/posts", { headers: doJoao, data: { legenda: "Bimestre inteiro sem faltar.", medalhaId: medalhaDoJoao } });
  const foto = readFileSync(path.join(SAIDA, "campus.jpg"));
  const upload = await (await request.post("/api/v1/uploads", {
    headers: daAna,
    data: { finalidade: "post", tipoDeConteudo: "image/jpeg", tamanhoDoFeed: foto.length, tamanhoDaGrade: foto.length > 200 * 1024 ? 0 : foto.length },
  })).json();
  // A grade da captura é a mesma foto reduzida pelo navegador; aqui basta o tamanho certo.
  const grade = readFileSync(path.join(SAIDA, "grade.jpg"));
  const uploadReal = await (await request.post("/api/v1/uploads", {
    headers: daAna,
    data: { finalidade: "post", tipoDeConteudo: "image/jpeg", tamanhoDoFeed: foto.length, tamanhoDaGrade: grade.length },
  })).json();
  void upload;
  expect((await request.put(uploadReal.feed.url, { headers: { "Content-Type": "image/jpeg" }, data: foto })).status()).toBe(200);
  expect((await request.put(uploadReal.grade.url, { headers: { "Content-Type": "image/jpeg" }, data: grade })).status()).toBe(200);
  const post = await (await request.post("/api/v1/posts", {
    headers: daAna,
    data: { legenda: "Finalmente registrei o pássaro raro do campus. Nota 10 na conta!", uploadId: uploadReal.id, medalhaId: medalhaDaAna },
  })).json();

  for (const quem of [doJoao, daProfessora]) {
    await request.put(`/api/v1/posts/${post.id}/curtida`, { headers: quem });
  }
  await request.post(`/api/v1/posts/${post.id}/comentarios`, { headers: doJoao, data: { texto: "Que foto! Esse pássaro é difícil de pegar." } });
  await request.post(`/api/v1/posts/${post.id}/comentarios`, { headers: daProfessora, data: { texto: "Parabéns pela nota, Ana." } });
  await request.post(`/api/v1/posts/${post.id}/comentarios`, { headers: daAna, data: { texto: "Valeu, professora!" } });

  await page.goto("/login");
  await page.getByLabel("RA ou e-mail").fill(ana.ra);
  await page.getByLabel("Senha", { exact: true }).fill(ana.senha);
  await page.getByRole("button", { name: "Entrar" }).click();
  await expect(page.getByTestId(`post-${post.id}`)).toBeVisible();
  await expect(page.getByTestId("foto-do-post").first()).toBeVisible();
  await page.waitForTimeout(800);
  const nossoFeed = path.join(SAIDA, `feed-${tema}.png`);
  await page.screenshot({ path: nossoFeed });

  await page.getByText("Ver todos os 3 comentários").click();
  await expect(page.getByText("Valeu, professora!")).toBeVisible();
  await page.waitForTimeout(500);
  const nossosComentarios = path.join(SAIDA, `comentarios-${tema}.png`);
  await page.screenshot({ path: nossosComentarios });

  const prancheta = path.resolve(__dirname, `../../design/telas/feed-${tema}.png`);
  await lado(page, nossoFeed, prancheta, path.join(SAIDA, `lado-feed-${tema}.png`), ["Prancheta do feed", "Maxx, etapa 8"]);
  await lado(page, nossosComentarios, prancheta, path.join(SAIDA, `lado-comentarios-${tema}.png`), [
    "Prancheta do feed (não há prancheta de comentários)",
    "Comentários, etapa 8",
  ]);
});

