            <Text
              role="heading"
              style={[textStyles.secao, styles.margem, styles.tituloDaSecao, { color: colors.ink }]}
            >
              Turmas neste semestre
            </Text>
          </View>
        }
        renderItem={({ item: turma }) => (
          <View style={[styles.margem, styles.turma, { borderBottomColor: colors.line }]}>
            <Text style={[textStyles.secao, { color: colors.ink }]}>{turma.materia}</Text>
            <Text style={[textStyles.legenda, { color: colors.ink2 }]}>
              {descreverTurma({ ...turma, alunos: undefined })}
            </Text>
          </View>
        )}
        ListEmptyComponent={
          <Text style={[textStyles.corpo, styles.margem, { color: colors.ink2 }]}>
            Nenhuma turma no semestre vigente.
          </Text>
        }
        ListFooterComponent={rodape}
      />
    );
  }

  return (
    <View
      style={[styles.fill, { backgroundColor: colors.bg }]}
      onLayout={(evento) => setLargura(evento.nativeEvent.layout.width)}
    >
      {aba === "posts" ? (
        <FlatList
          key="posts"
          testID="grade"
          data={lado > 0 ? listaDePosts : []}
          keyExtractor={(post) => post.id}
          numColumns={3}
          columnWrapperStyle={{ gap: VAO }}
          contentContainerStyle={{ paddingTop: insets.top, gap: VAO }}
          renderItem={({ item }: { item: Post }) => <CelulaDaGrade post={item} lado={lado} />}
          ListHeaderComponent={cabecalho}
          ListEmptyComponent={
            posts.isPending ? (
              <ActivityIndicator style={styles.espera} color={colors.ink2} />
            ) : posts.isError ? (
              <View style={styles.margem}>
                <ErrorState
                  message={falhaParaTela(posts.error).mensagem}
                  onRetry={() => void posts.refetch()}
                />
              </View>
            ) : (
              <View style={styles.margem}>
                <EmptyState
                  icon="imagem"
                  title={proprio ? "Você ainda não publicou." : "Nenhum post ainda."}
                />
              </View>
            )
          }
          ListFooterComponent={
            <View>
              {posts.isFetchingNextPage && <ActivityIndicator color={colors.ink2} />}
              {rodape}
            </View>
          }
          onEndReachedThreshold={0.5}
          onEndReached={() => {
            if (posts.hasNextPage && !posts.isFetchingNextPage) {
              void posts.fetchNextPage();
            }
          }}
        />
      ) : (
        <FlatList
          key={aba}
          data={itensDePremio}
          keyExtractor={(item) => item.codigo}
          contentContainerStyle={{ paddingTop: insets.top }}
          renderItem={({ item }) => (
            <View style={styles.margem}>
              <LinhaDePremio item={item} />
            </View>
          )}
          ListHeaderComponent={cabecalho}
          ListEmptyComponent={
            premios.isPending ? (
              <ActivityIndicator style={styles.espera} color={colors.ink2} />
            ) : premios.isError ? (
              <View style={styles.margem}>
                <ErrorState
                  message={falhaParaTela(premios.error).mensagem}
                  onRetry={() => void premios.refetch()}
                />
              </View>
            ) : (
              <View style={styles.margem}>
                <EmptyState
                  icon={aba === "medalhas" ? "fita" : "taca"}
                  title={aba === "medalhas" ? "Nenhuma medalha ainda." : "Nenhum troféu ainda."}
                />
              </View>
            )
          }
          ListFooterComponent={rodape}
        />
      )}
      <MenuDoPerfil
        aberto={menuAberto}
        professor={eu.data?.papeis.includes("professor") ?? false}
        onFechar={() => setMenuAberto(false)}
      />
    </View>
  );
}

// O cabeçalho do perfil: avatar, números, nome, linha de curso, botões.
function Cabecalho_({ perfil, proprio }: { perfil: Perfil; proprio: boolean }) {
  const { colors } = useTheme();
  const router = useRouter();
  const eu = useEu();
  const seguir = useSeguir(perfil.id);
  const ehAluno = perfil.papel === "aluno";
  const papeis = eu.data?.papeis ?? [];
  const leitorProfessor = papeis.includes("professor");
  const turmas = useTurmasEmComum(perfil.id, !proprio && ehAluno && leitorProfessor);
  const [concederEm, setConcederEm] = useState<string | null>(null);
  const [escolhendoTurma, setEscolhendoTurma] = useState(false);
  const [aviso, setAviso] = useState<string | null>(null);

  // Quem segue (produto.md 6.3): aluno segue aluno; professor, só os alunos dele. Quem já
  // segue sempre pode deixar de seguir.
  const podeSeguir =
    !proprio &&
    ehAluno &&
    (perfil.euSigo || papeis.includes("aluno") || (leitorProfessor && turmas.length > 0));

  const descricao = [
    perfil.ehAluno === undefined ? null : null,
    perfil.curso,
    perfil.semestre ? `${perfil.semestre}º semestre` : null,
    perfil.exAluno ? "Ex-aluno" : null,
    perfil.ra ? `RA ${perfil.ra}` : null,
  ]
    .filter(Boolean)
    .join(" · ");

  return (
    <View style={[styles.margem, styles.cabecalho]}>
      <View style={styles.linhaDoTopo}>
        <Avatar
          nome={perfil.nomeDeExibicao}
          foto={perfil.foto?.grade}
          size={84}
          anel={proprio && ehAluno}
        />
        {ehAluno && (
          <View style={[styles.pontos, { backgroundColor: colors.surface }]}>
            <Text style={[textStyles.titulo, { color: colors.ink }]}>
              {formatarNumero(perfil.pontos ?? 0)}
            </Text>
            <Text style={[textStyles.legenda, styles.forte, { color: colors.goldText }]}>pts</Text>
          </View>
        )}
        {ehAluno && <Contagem numero={perfil.seguidores} rotulo="seguidores" />}
        <Contagem numero={perfil.seguindo} rotulo="seguindo" />
      </View>

      <View style={styles.quem}>
        <Text style={[textStyles.titulo, { color: colors.ink }]}>{perfil.nomeDeExibicao}</Text>
        <Text testID="arroba" style={[textStyles.legenda, { color: colors.ink2 }]}>
          {perfil.arroba}
        </Text>
        {descricao !== "" && (
          <Text style={[textStyles.corpo, { color: colors.ink2 }]}>{descricao}</Text>
        )}
        {perfil.professor && (
          <Text style={[textStyles.corpo, { color: colors.ink2 }]}>
            {`Professor · ${formatarNumero(perfil.professor.medalhasConcedidas)} ${
              perfil.professor.medalhasConcedidas === 1 ? "medalha concedida" : "medalhas concedidas"
            }`}
          </Text>
        )}
      </View>

      <View style={styles.botoes}>
        {proprio && (
          <View style={styles.botao}>
            <Button
              label="Editar perfil"
              variant="secondary"
              onPress={() => router.push("/editar-perfil")}
            />
          </View>
        )}
        {podeSeguir && (
          <View style={styles.botao}>
            <Button
              label={seguir.isPending ? "Aguarde..." : perfil.euSigo ? "Seguindo" : "Seguir"}
              variant={perfil.euSigo ? "secondary" : "primary"}
              disabled={seguir.isPending}
              accessibilityLabel={
                perfil.euSigo ? `Deixar de seguir ${perfil.nomeDeExibicao}` : `Seguir ${perfil.nomeDeExibicao}`
              }
              onPress={() => {
                setAviso(null);
                seguir.mutate(!perfil.euSigo, {
                  onError: (erro) => setAviso(falhaParaTela(erro).mensagem),
                });
              }}
            />
          </View>
        )}
        {turmas.length > 0 && (
          <View style={styles.botao}>
            <Button
              label="Conceder medalha"
              variant="secondary"
              onPress={() =>
                turmas.length === 1 ? setConcederEm(turmas[0]!.id) : setEscolhendoTurma(true)
              }
            />
          </View>
        )}
      </View>

      {escolhendoTurma &&
        turmas.map((turma) => (
          <Button
            key={turma.id}
            label={`Em ${turma.materia}`}
            variant="secondary"
            onPress={() => {
              setEscolhendoTurma(false);
              setConcederEm(turma.id);
            }}
          />
        ))}
      {aviso && <AvisoDeErro mensagem={aviso} />}

      {concederEm && (
        <ModalDeConcessao
          turmaId={concederEm}
          aluno={{ id: perfil.id, nomeDeExibicao: perfil.nomeDeExibicao }}
          onFechar={() => setConcederEm(null)}
          onConcedida={(mensagem) => {
            setConcederEm(null);
            setAviso(mensagem);
          }}
        />
      )}
    </View>
  );
}

function Contagem({ numero, rotulo }: { numero: number; rotulo: string }) {
  const { colors } = useTheme();
  return (
    <View style={styles.contagem} accessible accessibilityLabel={`${numero} ${rotulo}`}>
      <Text style={[textStyles.titulo, { color: colors.ink }]}>{formatarNumero(numero)}</Text>
      <Text style={[textStyles.legenda, { color: colors.ink2 }]}>{rotulo}</Text>
    </View>
  );
}

