import { readFileSync } from "node:fs";
import path from "node:path";

import { expect, test, type APIRequestContext, type Page } from "@playwright/test";

import { novaConta } from "../tests/apoio/contas";
import { matricular, novaProfessora } from "../tests/apoio/medalhas";

// Captura temporária, fora do git: perfil próprio e de outro aluno ao lado da prancheta.
const SAIDA =
  "C:/Users/GUILHE~1/AppData/Local/Temp/claude/C--Users-Guilherme-Gimenes-Documents-Repos-tcc-maxx-engenheiro/db2e3dff-90c5-43a0-a9fa-f91217b12056/scratchpad";

async function token(request: APIRequestContext, identificador: string, senha: string) {
  const resposta = await request.post("/api/v1/auth/login", { data: { identificador, senha } });
  return { Authorization: `Bearer ${(await resposta.json()).accessToken}` };
}

async function lado(page: Page, nossa: string, prancheta: string, saida: string, legenda: [string, string]) {
  const dados = (arquivo: string) => `data:image/png;base64,${readFileSync(arquivo).toString("base64")}`;
  await page.setViewportSize({ width: 1600, height: 900 });
  await page.setContent(`
    <body style="margin:0;background:#888;font:600 28px sans-serif;color:#fff">
      <div id="par" style="display:flex;gap:24px;padding:24px;width:max-content">
        <figure style="margin:0"><figcaption style="padding-bottom:12px">${legenda[0]}</figcaption><img src="${dados(prancheta)}" width="780"></figure>
        <figure style="margin:0"><figcaption style="padding-bottom:12px">${legenda[1]}</figcaption><img src="${dados(nossa)}" width="780"></figure>
      </div>
    </body>`);
  await page.locator("#par").screenshot({ path: saida });
}

async function entrar(page: Page, identificador: string, senha: string) {
  await page.goto("/login");
  await page.getByLabel("RA ou e-mail").fill(identificador);
  await page.getByLabel("Senha", { exact: true }).fill(senha);
  await page.getByRole("button", { name: "Entrar", exact: true }).click();
  await expect(page).toHaveURL(/\/$/);
}

test("perfil próprio e de outro aluno", async ({ page, browser, request }, info) => {
  const tema = info.project.name;
  const ana = await novaConta(request, "Ana Souza");
  const joao = await novaConta(request, "João Lima");
  const professora = await novaProfessora(request);
  matricular(ana, professora.turmaId);
  matricular(joao, professora.turmaId);

  const daAna = await token(request, ana.ra, ana.senha);
  const doJoao = await token(request, joao.ra, joao.senha);
  const daProfessora = await token(request, professora.email, professora.senha);
  const n = ana.ra.slice(-4);
  await request.patch("/api/v1/eu/perfil", { headers: daAna, data: { prefixo: `anaSouza${n}` } });
  await request.patch("/api/v1/eu/perfil", { headers: doJoao, data: { prefixo: `joaoLima${n}` } });
  const idDaAna = (await (await request.get("/api/v1/eu", { headers: daAna })).json()).id;
  const idDoJoao = (await (await request.get("/api/v1/eu", { headers: doJoao })).json()).id;

  const conceder = async (item: string) =>
    (await (await request.post(`/api/v1/professor/turmas/${professora.turmaId}/medalhas`, {
      headers: daProfessora,
      data: { alunoId: idDaAna, item },
    })).json()).id;
  const nota10 = await conceder("M01");
  const presenca = await conceder("M03");
  const media10 = await conceder("M10");

  // Do mais antigo ao mais novo: a foto com a medalha, as duas medalhas sem foto e a legenda.
  const foto = readFileSync(path.join(SAIDA, "campus.jpg"));
  const grade = readFileSync(path.join(SAIDA, "grade.jpg"));
  const upload = await (await request.post("/api/v1/uploads", {
    headers: daAna,
    data: { finalidade: "post", tipoDeConteudo: "image/jpeg", tamanhoDoFeed: foto.length, tamanhoDaGrade: grade.length },
  })).json();
  await request.put(upload.feed.url, { headers: { "Content-Type": "image/jpeg" }, data: foto });
  await request.put(upload.grade.url, { headers: { "Content-Type": "image/jpeg" }, data: grade });
  await request.post("/api/v1/posts", { headers: daAna, data: { legenda: "Pássaro raro no campus!", uploadId: upload.id, medalhaId: nota10 } });
  await request.post("/api/v1/posts", { headers: daAna, data: { medalhaId: presenca } });
  await request.post("/api/v1/posts", { headers: daAna, data: { medalhaId: media10 } });
  await request.post("/api/v1/posts", { headers: daAna, data: { legenda: "Aprendendo a programar e fotografando o campus nos intervalos." } });
  await request.put(`/api/v1/seguindo/${idDaAna}`, { headers: doJoao });
  await request.put(`/api/v1/seguindo/${idDoJoao}`, { headers: daAna });

  // O próprio perfil, pela aba.
  await entrar(page, ana.ra, ana.senha);
  await page.getByRole("tab", { name: "Perfil" }).click();
  await expect(page.getByTestId("anel-do-avatar")).toBeVisible();
  await expect(page.locator('[data-testid^="celula-"]')).toHaveCount(4);
  await page.waitForTimeout(800);
  const proprio = path.join(SAIDA, `perfil-proprio-${tema}.png`);
  await page.screenshot({ path: proprio });

  // O perfil da Ana visto pelo João, que a segue.
  const contexto = await browser.newContext({ ...info.project.use, baseURL: "http://localhost:18080" });
  const doOutro = await contexto.newPage();
  await entrar(doOutro, joao.ra, joao.senha);
  await doOutro.goto(`/usuarios/${idDaAna}`);
  await expect(doOutro.getByRole("button", { name: /seguir Ana Souza/i })).toBeVisible();
  await expect(doOutro.locator('[data-testid^="celula-"]')).toHaveCount(4);
  await doOutro.waitForTimeout(800);
  const deOutro = path.join(SAIDA, `perfil-de-outro-${tema}.png`);
  await doOutro.screenshot({ path: deOutro });
  await contexto.close();

  const prancheta = path.resolve(__dirname, `../../design/telas/perfil-${tema}.png`);
  await lado(page, proprio, prancheta, path.join(SAIDA, `etapa9-perfil-proprio-${tema}.png`), ["Prancheta do perfil", "Perfil próprio, etapa 9"]);
  await lado(page, deOutro, prancheta, path.join(SAIDA, `etapa9-perfil-de-outro-${tema}.png`), [
    "Prancheta do perfil (próprio)",
    "Perfil de outro aluno, etapa 9",
  ]);
});

