  | { estado: "nao-verificado" };

function useValorParado<T>(valor: T, espera: number): T {
  const [parado, setParado] = useState(valor);
  useEffect(() => {
    const relogio = setTimeout(() => setParado(valor), espera);
    return () => clearTimeout(relogio);
  }, [valor, espera]);
  return parado;
}

