          if (busca.hasNextPage && !busca.isFetchingNextPage) {
            void busca.fetchNextPage();
          }
        }}
      />
      <View pointerEvents="none" style={styles.oculto}>
        <Icon name="search" color={colors.ink} size={1} />
      </View>
    </View>
  );
}

