import { readFileSync } from "node:fs";
import path from "node:path";

import { expect, test, type APIRequestContext } from "@playwright/test";

import { novaConta } from "../tests/apoio/contas";

// Captura temporária, fora do git: busca e editar perfil, que não têm prancheta.
const SAIDA =
  "C:/Users/GUILHE~1/AppData/Local/Temp/claude/C--Users-Guilherme-Gimenes-Documents-Repos-tcc-maxx-engenheiro/db2e3dff-90c5-43a0-a9fa-f91217b12056/scratchpad";

async function token(request: APIRequestContext, identificador: string, senha: string) {
  const resposta = await request.post("/api/v1/auth/login", { data: { identificador, senha } });
  return { Authorization: `Bearer ${(await resposta.json()).accessToken}` };
}

test("busca e editar perfil", async ({ page, request }, info) => {
  const tema = info.project.name;
  const n = `${Date.now()}`.slice(-4);
  const ana = await novaConta(request, "Ana Souza");
  const daAna = await token(request, ana.ra, ana.senha);
  await request.patch("/api/v1/eu/perfil", { headers: daAna, data: { prefixo: `anaSouza${n}` } });

  // Colegas com nomes que a busca por "jo" encontra, um deles seguido pela Ana.
  for (const nome of ["João Lima", "Joana Prado", "Jonas Ávila"]) {
    const colega = await novaConta(request, nome);
    const doColega = await token(request, colega.ra, colega.senha);
    const prefixo = nome.normalize("NFD").replace(/[^A-Za-z]/g, "");
    await request.patch("/api/v1/eu/perfil", { headers: doColega, data: { prefixo: `${prefixo}${n}` } });
    if (nome === "João Lima") {
      const id = (await (await request.get("/api/v1/eu", { headers: doColega })).json()).id;
      await request.put(`/api/v1/seguindo/${id}`, { headers: daAna });
    }
  }

  // A foto de perfil da Ana, pelo mesmo caminho do app.
  const feed = readFileSync(path.join(SAIDA, "campus.jpg"));
  const grade = readFileSync(path.join(SAIDA, "grade.jpg"));
  const upload = await (await request.post("/api/v1/uploads", {
    headers: daAna,
    data: { finalidade: "fotoDePerfil", tipoDeConteudo: "image/jpeg", tamanhoDoFeed: feed.length, tamanhoDaGrade: grade.length },
  })).json();
  await request.put(upload.feed.url, { headers: { "Content-Type": "image/jpeg" }, data: feed });
  await request.put(upload.grade.url, { headers: { "Content-Type": "image/jpeg" }, data: grade });
  expect((await request.patch("/api/v1/eu/perfil", { headers: daAna, data: { fotoUploadId: upload.id } })).status()).toBe(200);

  await page.goto("/login");
  await page.getByLabel("RA ou e-mail").fill(ana.ra);
  await page.getByLabel("Senha", { exact: true }).fill(ana.senha);
  await page.getByRole("button", { name: "Entrar", exact: true }).click();
  await expect(page).toHaveURL(/\/$/);

  await page.getByRole("tab", { name: "Busca" }).click();
  await page.getByLabel("Buscar").fill("jo");
  await page.getByRole("radio", { name: "CC" }).click();
  await expect(page.getByText(`@joaoLima${n}-CC`, { exact: false })).toBeVisible();
  await page.waitForTimeout(800);
  await page.screenshot({ path: path.join(SAIDA, `etapa10-busca-${tema}.png`) });

  await page.getByRole("tab", { name: "Perfil" }).click();
  await page.getByRole("button", { name: "Editar perfil" }).click();
  await expect(page.getByTestId("foto-de-perfil")).toBeVisible();
  await page.getByLabel("Nome de exibição").fill("Ana Souza");
  await page.getByLabel("Arroba").fill(`aninha${n}`);
  await page.waitForTimeout(1200);
  await page.screenshot({ path: path.join(SAIDA, `etapa10-editar-perfil-${tema}.png`) });
});

