{
    await using var mundo = await CriarAsync(postgres, armazenamento);
    using var ana = await mundo.ComoAsync(Ana);
    await MedicinaAsync(mundo);

    var doDecimoSegundo = await BuscarAsync(ana, "semestre=12");
