import { writeFileSync } from "node:fs";

import { expect, test, type Page } from "@playwright/test";

import { novaConta, type Aluno } from "./apoio/contas";
import { abrirPerfil } from "./apoio/navegacao";

// O passo 7 de ponta a ponta: post com foto subindo de verdade ao bucket (o emulador do
// compose na CI), deep link atrás do login, curtida, comentário e remoção, busca, seguir e
// editar perfil. Só no celular, como os outros fluxos com conta, pelo limite de login por IP.

async function entrar(page: Page, aluno: Aluno) {
  await page.getByLabel("RA ou e-mail").fill(aluno.ra);
  await page.getByLabel("Senha", { exact: true }).fill(aluno.senha);
  await page.getByRole("button", { name: "Entrar", exact: true }).click();
}

// Uma foto de verdade, desenhada no navegador e salva como JPEG: nada binário no repositório.
async function fotoDeTeste(page: Page, caminho: string) {
  await page.setContent("<canvas id=c width=1200 height=900></canvas>");
  const base64 = await page.evaluate(() => {
    const canvas = document.getElementById("c") as HTMLCanvasElement;
    const contexto = canvas.getContext("2d")!;
    const ceu = contexto.createLinearGradient(0, 0, 0, 900);
    ceu.addColorStop(0, "#8ec5ff");
    ceu.addColorStop(1, "#0b2a55");
    contexto.fillStyle = ceu;
    contexto.fillRect(0, 0, 1200, 900);
    contexto.fillStyle = "#f5b400";
    contexto.beginPath();
    contexto.arc(600, 450, 220, 0, Math.PI * 2);
    contexto.fill();
    return canvas.toDataURL("image/jpeg", 0.9).split(",")[1];
  });
  writeFileSync(caminho, Buffer.from(base64!, "base64"));
}

test(
  "post com foto, deep link depois do login, curtida e comentário apagado",
  { tag: "@celular" },
  async ({ browser, page, request }, info) => {
    const autora = await novaConta(request, "Autora E2E");
    const leitor = await novaConta(request, "Leitor E2E");
    const foto = info.outputPath("foto.jpg");
    await fotoDeTeste(page, foto);
    const legenda = `Post de ponta a ponta ${Date.now()}`;

    // A autora publica pelo "+" do feed, com a foto da galeria (o seletor de arquivo na web).
    await page.goto("/login");
    await entrar(page, autora);
    // O "+" do cabeçalho; com o feed vazio, o estado vazio também oferece "Novo post".
    await page.getByRole("button", { name: "Novo post" }).first().click();
    const seletor = page.waitForEvent("filechooser");
    await page.getByRole("button", { name: "Escolher foto" }).click();
    await (await seletor).setFiles(foto);
    await expect(page.getByTestId("previa-da-foto")).toBeVisible();
    await page.getByLabel("Legenda").fill(legenda);
    await page.getByRole("button", { name: "Publicar" }).click();

    // No feed, com a foto carregada do bucket.
    const cartao = page.locator('[data-testid^="post-"]', { hasText: legenda });
    await expect(cartao).toBeVisible();
    const imagem = cartao.getByTestId("foto-do-post").locator("img");
    await expect
      .poll(() => imagem.evaluate((img: HTMLImageElement) => img.naturalWidth))
      .toBeGreaterThan(0);
    const postId = (await cartao.getAttribute("data-testid"))!.replace(
      "post-",
      "",
    );

    // O leitor chega pelo link do post sem sessão, entra e cai no post.
    const contexto = await browser.newContext(info.project.use);
    const doLeitor = await contexto.newPage();
    await doLeitor.goto(`/post/${postId}`);
    await expect(doLeitor).toHaveURL(/\/login\?voltar=%2Fpost%2F/);
    await entrar(doLeitor, leitor);
    await expect(doLeitor).toHaveURL(new RegExp(`/post/${postId}$`));
    await expect(doLeitor.getByText(legenda)).toBeVisible();

    await doLeitor.getByRole("button", { name: "Curtir" }).click();
    await expect(doLeitor.getByText("1 curtida")).toBeVisible();
    await expect(
      doLeitor.getByRole("button", { name: "Descurtir" }),
    ).toBeVisible();

    await doLeitor.getByRole("button", { name: "Comentários" }).click();
    await doLeitor.getByLabel("Comentário").fill("Que foto bonita!");
    await doLeitor.getByRole("button", { name: "Publicar" }).click();
    await expect(doLeitor.getByText("Que foto bonita!")).toBeVisible();
    await doLeitor.getByText("Apagar").click();
    await expect(doLeitor.getByText("Nenhum comentário ainda.")).toBeVisible();
    await contexto.close();
  },
);

test(
  "busca acha o colega, seguir conta no perfil e editar perfil troca nome e arroba",
  { tag: "@celular" },
  async ({ page, request }) => {
    const n = `${Date.now()}`.slice(-7);
    const aluna = await novaConta(request, "Aluna E2E");
    await novaConta(request, `Colega Raro ${n}`);

    await page.goto("/login");
    await entrar(page, aluna);
    await page.getByRole("tab", { name: "Busca" }).click();
    await page.getByLabel("Buscar").fill(`raro ${n}`);
    await page
      .getByRole("link", { name: new RegExp(`^Colega Raro ${n}`) })
      .click();

    await page.getByRole("button", { name: `Seguir Colega Raro ${n}` }).click();
    await expect(
      page.getByRole("button", { name: `Deixar de seguir Colega Raro ${n}` }),
    ).toBeVisible();
    await expect(page.getByLabel("1 seguidores")).toBeVisible();

    // O perfil de outra pessoa abre fora das abas: volta para a Busca antes.
    await page.getByRole("button", { name: "Voltar" }).click();
    await abrirPerfil(page);
    await expect(page.getByLabel("1 seguindo")).toBeVisible();
    await page.getByRole("button", { name: "Editar perfil" }).click();
    await page.getByLabel("Nome de exibição").fill("Aluna Editada");
    await page.getByLabel("Arroba").fill(`editada${n}`);
    await expect(page.getByRole("button", { name: "Salvar" })).toBeEnabled();
    await page.getByRole("button", { name: "Salvar" }).click();

    await expect(page.getByTestId("arroba")).toHaveText(`@editada${n}-CC`);
    await expect(page.getByText("Aluna Editada")).toBeVisible();
  },
);

import { expect, test, type Browser, type Page } from "@playwright/test";

import { novaConta } from "./apoio/contas";
import { abrirMenu } from "./apoio/navegacao";
import {
  anularMedalha,
  matricular,
  medalhaAtiva,
  novaProfessora,
} from "./apoio/medalhas";

// O passo 6 de ponta a ponta (fluxos/03-concessao-de-medalha.md): a professora concede pela
// lista da turma, o aluno vê em Troféus, e o comando administrativo anula. Só no celular,
// claro e escuro; cada execução tem a sua professora e o seu aluno.

async function entrar(page: Page, identificador: string, senha: string) {
  await page.goto("/login");
  await page.getByLabel("RA ou e-mail").fill(identificador);
  await page.getByLabel("Senha", { exact: true }).fill(senha);
  await page.getByRole("button", { name: "Entrar" }).click();
}

// Uma página com sessão própria, no tamanho e no tema do projeto (celular claro ou escuro).
async function novaPagina(browser: Browser): Promise<Page> {
  const { viewport, isMobile, hasTouch, colorScheme, baseURL } =
    test.info().project.use;
  const contexto = await browser.newContext({
    viewport,
    isMobile,
    hasTouch,
    colorScheme,
    baseURL,
  });
  return contexto.newPage();
}

async function medalhasDoAluno(page: Page) {
  await page.getByRole("tab", { name: "Troféus" }).click();
  await page.getByRole("tab", { name: "Medalhas" }).click();
}

test(
  "a professora concede, o aluno vê em Troféus e a anulação tira a medalha",
  { tag: "@celular" },
  async ({ browser, request }) => {
    const professora = await novaProfessora(request);
    const n = Date.now().toString().slice(-6);
    const nome = `Aluno ${n}`;
    const aluno = await novaConta(request, nome);
    matricular(aluno, professora.turmaId);

    // A professora, pela lista da turma e pelo modal do catálogo.
    const daProfessora = await novaPagina(browser);
    await entrar(daProfessora, professora.email, professora.senha);
    await abrirMenu(daProfessora);
    await daProfessora.getByRole("button", { name: "Minhas turmas" }).click();
    await daProfessora.getByRole("button", { name: /^Banco de Dados/ }).click();
    await daProfessora
      .getByRole("button", { name: `Conceder medalha a ${nome}` })
      .click();
    await expect(daProfessora.getByText(`Para ${nome}`)).toBeVisible();
    await daProfessora
      .getByRole("radio", { name: /^Nota 10 em prova, Bronze, 30 pontos/ })
      .click();
    await daProfessora
      .getByRole("button", { name: "Conceder", exact: true })
      .click();
    await expect(
      daProfessora.getByText(`Medalha Nota 10 em prova concedida a ${nome}.`),
    ).toBeVisible();
    await daProfessora.close();

    // O aluno, na aba Medalhas da tela de Troféus.
    const doAluno = await novaPagina(browser);
    await entrar(doAluno, aluno.ra, aluno.senha);
    await medalhasDoAluno(doAluno);
    const linha = doAluno.getByTestId("premio-M01");
    await expect(doAluno.getByText("30 pts", { exact: true })).toBeVisible();
    await expect(linha.getByText("+30")).toBeVisible();
    await expect(
      linha.getByText("Banco de Dados · ", { exact: false }),
    ).toBeVisible();

    // A instituição anula pelo comando administrativo.
    expect(anularMedalha(medalhaAtiva(aluno))).toContain("anulada.");

    await doAluno.reload();
    await medalhasDoAluno(doAluno);
    await expect(doAluno.getByText("0 pts", { exact: true })).toBeVisible();
    await expect(
      doAluno.getByTestId("premio-M01").getByText("+30"),
    ).toHaveCount(0);
    await doAluno.close();
  },
);

import { act, fireEvent, screen } from "@testing-library/react-native";
import { launchImageLibraryAsync } from "expo-image-picker";

import { json, renderComApi } from "../test/renderComApi";
import { EditarPerfilScreen } from "./EditarPerfilScreen";

const mockRoteador = {
  push: jest.fn(),
  replace: jest.fn(),
  back: jest.fn(),
  canGoBack: jest.fn(() => true),
};
jest.mock("expo-router", () => ({ useRouter: () => mockRoteador }));
jest.mock("expo-image-picker", () => ({ launchImageLibraryAsync: jest.fn() }));
jest.mock("expo-image-manipulator", () => {
  let gerada = 0;
  return {
    SaveFormat: { JPEG: "jpeg" },
    ImageManipulator: {
      manipulate: () => {
        const contexto = {
          crop: () => contexto,
          resize: () => contexto,
          renderAsync: async () => ({
            saveAsync: async () => ({
              uri: `file:///derivada-${++gerada}.jpg`,
              width: 0,
              height: 0,
            }),
          }),
        };
        return contexto;
      },
    },
  };
});

const ANA = "0193a000-0000-7000-8000-0000000000b1";

const PERFIL = {
  id: ANA,
  nomeDeExibicao: "Ana Souza",
  arroba: "@anaSouza-CC",
  papel: "aluno",
  curso: "CC",
  nomeDoCurso: "Ciência da Computação",
  semestre: 3,
  exAluno: false,
  ra: "20260101",
  pontos: 30,
  seguidores: 0,
  seguindo: 0,
  euSigo: false,
  foto: null as null | { feed: string; grade: string },
  professor: null,
};

let perfil: typeof PERFIL;
let edicao: jest.Mock<Promise<Response>, [Request]>;
let disponibilidade: jest.Mock<Promise<Response>, [Request]>;
let api: jest.Mock<Promise<Response>, [Request]>;
let rede: jest.SpyInstance;

beforeEach(() => {
  jest.clearAllMocks();
  perfil = { ...PERFIL };
  edicao = jest.fn(async (_pedido: Request) => json(200, perfil));
  disponibilidade = jest.fn(async (_pedido: Request) =>
    json(200, { disponivel: true }),
  );
  api = jest.fn(async (pedido: Request) => {
    const { pathname } = new URL(pedido.url);
    if (pathname === "/api/v1/eu/perfil" && pedido.method === "PATCH")
      return edicao(pedido);
    if (pathname === "/api/v1/eu/perfil") return json(200, perfil);
    if (pathname === "/api/v1/eu/perfil/disponibilidade")
      return disponibilidade(pedido);
    if (pathname === "/api/v1/uploads")
      return json(201, {
        id: "upload-1",
        expiraEm: "2026-11-10T13:15:00Z",
        feed: {
          url: "http://bucket.test/a/feed.jpg",
          tipoDeConteudo: "image/jpeg",
          tamanho: 300,
        },
        grade: {
          url: "http://bucket.test/a/grade.jpg",
          tipoDeConteudo: "image/jpeg",
          tamanho: 40,
        },
      });
    return new Response(null, { status: 404 });
  });
  rede = jest
    .spyOn(global, "fetch")
    .mockImplementation(async (entrada: RequestInfo | URL) =>
      String(entrada).startsWith("file:///")
        ? new Response(new Blob([new Uint8Array(100)]))
        : new Response(null, { status: 200 }),
    );
  jest.mocked(launchImageLibraryAsync).mockResolvedValue({
    canceled: false,
    assets: [{ uri: "file:///galeria.jpg", width: 1000, height: 1000 }],
  } as never);
});

afterEach(() => rede.mockRestore());

const corpoDaEdicao = async () => edicao.mock.calls[0]![0].clone().json();

async function apertar(nome: string) {
  await act(async () => {
    fireEvent.press(await screen.findByRole("button", { name: nome }));
  });
}

async function escrever(rotulo: string, texto: string) {
  await act(async () => {
    fireEvent.changeText(await screen.findByLabelText(rotulo), texto);
  });
}

describe("editar perfil", () => {
  it("mostra o que está valendo e só deixa salvar quando algo muda", async () => {
    await renderComApi(<EditarPerfilScreen />, api);

    expect((await screen.findByLabelText("Nome de exibição")).props.value).toBe(
      "Ana Souza",
    );
    expect(screen.getByLabelText("Arroba").props.value).toBe("anaSouza");
    expect(screen.getByText(/Seu arroba: @anaSouza-CC/)).toBeOnTheScreen();
    expect(screen.getByRole("button", { name: "Salvar" })).toBeDisabled();
  });

  it("salva só o nome que mudou e volta", async () => {
    await renderComApi(<EditarPerfilScreen />, api);

    await escrever("Nome de exibição", "  Aninha  ");
    await apertar("Salvar");

    expect(await corpoDaEdicao()).toEqual({
      nomeDeExibicao: "Aninha",
      prefixo: null,
      fotoUploadId: null,
      removerFoto: null,
    });
    expect(mockRoteador.back).toHaveBeenCalled();
  });

  it("confere o prefixo novo depois que a digitação para e salva se estiver livre", async () => {
    await renderComApi(<EditarPerfilScreen />, api);

    await escrever("Arroba", "aninha");
    expect(await screen.findByText(/Seu arroba: @aninha-CC/)).toBeOnTheScreen();
    await act(async () => {
      await new Promise((pronto) => setTimeout(pronto, 600));
    });
    expect(
      new URL(disponibilidade.mock.calls[0]![0].url).searchParams.get(
        "prefixo",
      ),
    ).toBe("aninha");

    await apertar("Salvar");
    expect((await corpoDaEdicao()).prefixo).toBe("aninha");
  });

  it("prefixo de outra pessoa ou fora da forma mostra o erro no campo e não salva", async () => {
    disponibilidade.mockResolvedValue(json(200, { disponivel: false }));
    await renderComApi(<EditarPerfilScreen />, api);

    await escrever("Arroba", "brunoLima");
    expect(
      await screen.findByText(
        "Esse arroba já é de outra pessoa.",
        {},
        { timeout: 2000 },
      ),
    ).toBeOnTheScreen();
    expect(screen.getByRole("button", { name: "Salvar" })).toBeDisabled();

    await escrever("Arroba", "a-b");
    expect(screen.getByText(/Use de 3 a 30 letras/)).toBeOnTheScreen();
  });

  it("recusa da API vira mensagem amigável", async () => {
    edicao.mockResolvedValue(json(409, { codigo: "prefixo-indisponivel" }));
    await renderComApi(<EditarPerfilScreen />, api);

    await escrever("Nome de exibição", "Aninha");
    await apertar("Salvar");

    expect(await screen.findByRole("alert")).toBeOnTheScreen();
    expect(mockRoteador.back).not.toHaveBeenCalled();
  });

  it("foto nova sobe como foto de perfil e vai no pedido pelo upload", async () => {
    await renderComApi(<EditarPerfilScreen />, api);

    await apertar("Escolher foto");
    expect(await screen.findByTestId("foto-de-perfil")).toBeOnTheScreen();
    await apertar("Salvar");

    const pedidoDeUpload = api.mock.calls.find(
      ([pedido]) => new URL(pedido.url).pathname === "/api/v1/uploads",
    )!;
    expect((await pedidoDeUpload[0].clone().json()).finalidade).toBe(
      "fotoDePerfil",
    );
    expect((await corpoDaEdicao()).fotoUploadId).toBe("upload-1");
  });

  it("remover a foto manda removerFoto", async () => {
    perfil = {
      ...PERFIL,
      foto: {
        feed: "http://fotos.test/f.jpg",
        grade: "http://fotos.test/g.jpg",
      },
    };
    await renderComApi(<EditarPerfilScreen />, api);

    await apertar("Remover foto");
    await apertar("Salvar");

    expect(await corpoDaEdicao()).toEqual(
      expect.objectContaining({ removerFoto: true, fotoUploadId: null }),
    );
  });
});

import { act, fireEvent, screen } from "@testing-library/react-native";

import { json, renderComApi } from "../test/renderComApi";
import { BuscaScreen } from "./BuscaScreen";

const mockRoteador = {
  push: jest.fn(),
  replace: jest.fn(),
  back: jest.fn(),
  canGoBack: jest.fn(() => true),
};
jest.mock("expo-router", () => ({ useRouter: () => mockRoteador }));

const ANA = "0193a000-0000-7000-8000-0000000000b1";
const JOAO = "0193a000-0000-7000-8000-0000000000b2";

const JOAO_ENCONTRADO = {
  id: JOAO,
  nomeDeExibicao: "João Lima",
  arroba: "@joaoLima-CC",
  curso: "CC",
  semestre: 5,
  exAluno: false,
